/* avpcore str: views, search, strip, split, partition, replace, join, padding, the builder and the UTF-8 / UTF-16
 * conversions. Each function reproduces the CPython 3.14 str method it is named after, edge cases included; the
 * tests compare against a corpus generated by CPython (tests/str_corpus.h).
 *
 * Text is UTF-8. Where Python counts code points the code decodes them with avp_u8_next; a byte that is not part of
 * a valid sequence counts as one code point U+FFFD (the Python side would have had surrogateescape or an error). */
#include "avp/avp.h"

#include <stdio.h>
#include <stdlib.h>
#include <wchar.h>

#include "str_internal.h"

/* ---- views -------------------------------------------------------------------------------------------------------- */

AvpStr avp_str(const char *cz) {
    AvpStr s;
    s.p = cz ? cz : "";
    s.n = cz ? strlen(cz) : 0;
    return s;
}

AvpStr avp_strn(const char *p, size_t n) {
    AvpStr s;
    s.p = p ? p : "";
    s.n = n;
    return s;
}

char *avp_cz(AvpArena *a, AvpStr s) {
    char *p = (char *)avp_alloc_noz(a, s.n + 1);
    if (s.n) memcpy(p, s.p, s.n);
    p[s.n] = 0;
    return p;
}

AvpStr avp_str_dup(AvpArena *a, AvpStr s) { return avp_strn(avp_cz(a, s), s.n); }

bool avp_str_eq(AvpStr a, AvpStr b) { return a.n == b.n && (a.n == 0 || memcmp(a.p, b.p, a.n) == 0); }

bool avp_str_eqz(AvpStr a, const char *cz) {
    size_t n = strlen(cz);
    return a.n == n && (n == 0 || memcmp(a.p, cz, n) == 0);
}

int avp_str_cmp(AvpStr a, AvpStr b) {
    size_t n = AVP_MIN(a.n, b.n);
    int c = n ? memcmp(a.p, b.p, n) : 0;
    if (c) return c;
    return a.n < b.n ? -1 : a.n > b.n ? 1 : 0;
}

bool avp_str_startswith(AvpStr s, AvpStr prefix) {
    return prefix.n <= s.n && (prefix.n == 0 || memcmp(s.p, prefix.p, prefix.n) == 0);
}

bool avp_str_endswith(AvpStr s, AvpStr suffix) {
    return suffix.n <= s.n && (suffix.n == 0 || memcmp(s.p + s.n - suffix.n, suffix.p, suffix.n) == 0);
}

/* ---- UTF-8 -------------------------------------------------------------------------------------------------------- */

u32 avp_u8_next(const char **pp, const char *end) {
    const u8 *p = (const u8 *)*pp;
    const u8 *e = (const u8 *)end;
    AVP_ASSERT(p < e);
    u32 c = p[0];
    if (c < 0x80) {
        *pp += 1;
        return c;
    }
    if (c >= 0xC2 && c <= 0xDF) {
        if (e - p >= 2 && (p[1] & 0xC0) == 0x80) {
            *pp += 2;
            return ((c & 0x1Fu) << 6) | (p[1] & 0x3Fu);
        }
    } else if (c >= 0xE0 && c <= 0xEF) {
        if (e - p >= 3) {
            u8 lo = 0x80, hi = 0xBF;
            if (c == 0xE0) lo = 0xA0;
            else if (c == 0xED) hi = 0x9F; /* no surrogates */
            if (p[1] >= lo && p[1] <= hi && (p[2] & 0xC0) == 0x80) {
                *pp += 3;
                return ((c & 0x0Fu) << 12) | ((p[1] & 0x3Fu) << 6) | (p[2] & 0x3Fu);
            }
        }
    } else if (c >= 0xF0 && c <= 0xF4) {
        if (e - p >= 4) {
            u8 lo = 0x80, hi = 0xBF;
            if (c == 0xF0) lo = 0x90;
            else if (c == 0xF4) hi = 0x8F; /* nothing above U+10FFFF */
            if (p[1] >= lo && p[1] <= hi && (p[2] & 0xC0) == 0x80 && (p[3] & 0xC0) == 0x80) {
                *pp += 4;
                return ((c & 0x07u) << 18) | ((p[1] & 0x3Fu) << 12) | ((p[2] & 0x3Fu) << 6) | (p[3] & 0x3Fu);
            }
        }
    }
    *pp += 1;
    return 0xFFFD;
}

u32 avp__u8_prev(const char *begin, const char **pp) {
    const char *p = *pp;
    AVP_ASSERT(p > begin);
    if ((u8)p[-1] < 0x80) {
        *pp = p - 1;
        return (u8)p[-1];
    }
    for (const char *q = p - 1; q >= begin && p - q <= 4; q--) {
        if (((u8)*q & 0xC0) == 0x80) continue; /* a continuation byte: look further back for the lead */
        const char *r = q;
        u32 cp = avp_u8_next(&r, p);
        if (r == p) {
            *pp = q;
            return cp;
        }
        break;
    }
    *pp = p - 1;
    return 0xFFFD;
}

size_t avp_u8_put(char out[4], u32 cp) {
    if (cp >= 0xD800 && cp <= 0xDFFF) cp = 0xFFFD;
    if (cp > 0x10FFFF) cp = 0xFFFD;
    if (cp < 0x80) {
        out[0] = (char)cp;
        return 1;
    }
    if (cp < 0x800) {
        out[0] = (char)(0xC0 | (cp >> 6));
        out[1] = (char)(0x80 | (cp & 0x3F));
        return 2;
    }
    if (cp < 0x10000) {
        out[0] = (char)(0xE0 | (cp >> 12));
        out[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        out[2] = (char)(0x80 | (cp & 0x3F));
        return 3;
    }
    out[0] = (char)(0xF0 | (cp >> 18));
    out[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
    out[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
    out[3] = (char)(0x80 | (cp & 0x3F));
    return 4;
}

size_t avp_u8_len(AvpStr s) {
    const char *p = s.p, *end = s.p + s.n;
    size_t n = 0;
    while (p < end) {
        if ((u8)*p < 0x80) p++;
        else avp_u8_next(&p, end);
        n++;
    }
    return n;
}

bool avp_u8_valid(AvpStr s) {
    const char *p = s.p, *end = s.p + s.n;
    while (p < end) {
        if ((u8)*p < 0x80) {
            p++;
            continue;
        }
        const char *q = p;
        u32 cp = avp_u8_next(&q, end);
        if (cp == 0xFFFD && q - p == 1) return false;
        p = q;
    }
    return true;
}

/* Byte offset of the code point index (0-based, at most the code point count) counted from the start of s. */
static const char *u8_advance(const char *p, const char *end, i64 count) {
    while (count > 0 && p < end) {
        if ((u8)*p < 0x80) p++;
        else avp_u8_next(&p, end);
        count--;
    }
    return p;
}

AvpStr avp_u8_slice(AvpStr s, i64 i, i64 j) {
    if (i < 0 || j < 0) {
        i64 len = (i64)avp_u8_len(s);
        if (i < 0) {
            i += len;
            if (i < 0) i = 0;
        }
        if (j < 0) {
            j += len;
            if (j < 0) j = 0;
        }
    }
    if (j <= i) return avp_strn(s.p, 0);
    const char *end = s.p + s.n;
    const char *start = u8_advance(s.p, end, i);
    const char *stop = u8_advance(start, end, j - i);
    return avp_strn(start, (size_t)(stop - start));
}

/* ---- search ------------------------------------------------------------------------------------------------------- */

/* Two-way string matching (Crochemore-Perrin), the algorithm CPython uses for long needles: linear time with no
 * table. rev reads both strings backwards, which turns the search for the first match into one for the last. */
static inline u8 at(const char *p, size_t n, size_t i, int rev) { return (u8)(rev ? p[n - 1 - i] : p[i]); }

/* The critical factorization position and the period of the needle's suffix after it. */
static void critical_factorization(const char *nd, size_t nn, int rev, size_t *crit, size_t *period) {
    i64 ms = -1, msr = -1;
    size_t j = 0, k = 1, p = 1, p1, p2;
    while (j + k < nn) {
        u8 a = at(nd, nn, j + k, rev), b = at(nd, nn, (size_t)(ms + (i64)k), rev);
        if (a < b) {
            j += k;
            k = 1;
            p = (size_t)((i64)j - ms);
        } else if (a == b) {
            if (k != p) k++;
            else {
                j += p;
                k = 1;
            }
        } else {
            ms = (i64)j++;
            k = p = 1;
        }
    }
    p1 = p;
    j = 0;
    k = p = 1;
    while (j + k < nn) {
        u8 a = at(nd, nn, j + k, rev), b = at(nd, nn, (size_t)(msr + (i64)k), rev);
        if (b < a) {
            j += k;
            k = 1;
            p = (size_t)((i64)j - msr);
        } else if (a == b) {
            if (k != p) k++;
            else {
                j += p;
                k = 1;
            }
        } else {
            msr = (i64)j++;
            k = p = 1;
        }
    }
    p2 = p;
    if (msr < ms) {
        *crit = (size_t)(ms + 1);
        *period = p1;
    } else {
        *crit = (size_t)(msr + 1);
        *period = p2;
    }
}

/* The offset (in the direction of reading) of the first occurrence of nd (nn >= 2) in h (hn >= nn), or SIZE_MAX. */
static size_t two_way(const char *h, size_t hn, const char *nd, size_t nn, int rev) {
    size_t suffix, period;
    critical_factorization(nd, nn, rev, &suffix, &period);
    bool periodic = suffix + period <= nn;
    if (periodic) {
        for (size_t i = 0; i < suffix; i++)
            if (at(nd, nn, i, rev) != at(nd, nn, i + period, rev)) {
                periodic = false;
                break;
            }
    }
    size_t j = 0;
    if (periodic) {
        size_t memory = 0;
        while (j <= hn - nn) {
            size_t i = AVP_MAX(suffix, memory);
            while (i < nn && at(nd, nn, i, rev) == at(h, hn, i + j, rev)) i++;
            if (i >= nn) {
                /* The right half matched: check the left half beyond what is remembered. */
                i64 l = (i64)suffix - 1;
                while ((i64)memory < l + 1 && at(nd, nn, (size_t)l, rev) == at(h, hn, (size_t)l + j, rev)) l--;
                if (l + 1 <= (i64)memory) return j;
                j += period;
                memory = nn - period;
            } else {
                j += i - suffix + 1;
                memory = 0;
            }
        }
    } else {
        period = AVP_MAX(suffix, nn - suffix) + 1;
        while (j <= hn - nn) {
            size_t i = suffix;
            while (i < nn && at(nd, nn, i, rev) == at(h, hn, i + j, rev)) i++;
            if (i >= nn) {
                i64 l = (i64)suffix - 1;
                while (l >= 0 && at(nd, nn, (size_t)l, rev) == at(h, hn, (size_t)l + j, rev)) l--;
                if (l < 0) return j;
                j += period;
            } else {
                j += i - suffix + 1;
            }
        }
    }
    return SIZE_MAX;
}

/* First occurrence of the non-empty needle in h; NULL when absent. */
static const char *search_fwd(const char *h, size_t hn, const char *nd, size_t nn) {
    if (hn < nn) return NULL;
    if (nn == 1) return (const char *)memchr(h, (u8)nd[0], hn);
    if (nn <= 16 || hn - nn < 64) {
        /* Short needles: the first byte through memchr, then a compare; bounded by nn * hn, which is linear. */
        const char *last = h + (hn - nn);
        for (const char *p = h; p <= last;) {
            p = (const char *)memchr(p, (u8)nd[0], (size_t)(last - p) + 1);
            if (!p) return NULL;
            if (memcmp(p, nd, nn) == 0) return p;
            p++;
        }
        return NULL;
    }
    size_t r = two_way(h, hn, nd, nn, 0);
    return r == SIZE_MAX ? NULL : h + r;
}

/* Last occurrence of the non-empty needle in h; NULL when absent. */
static const char *search_rev(const char *h, size_t hn, const char *nd, size_t nn) {
    if (hn < nn) return NULL;
    if (nn <= 16 || hn - nn < 64) {
        for (const char *p = h + (hn - nn);; p--) {
            if (p[0] == nd[0] && memcmp(p, nd, nn) == 0) return p;
            if (p == h) return NULL;
        }
    }
    size_t r = two_way(h, hn, nd, nn, 1);
    return r == SIZE_MAX ? NULL : h + (hn - nn - r);
}

/* Python's ADJUST_INDICES: slice semantics for [start, end) over len bytes. start may stay above len. */
static void adjust(i64 *start, i64 *end, i64 len) {
    if (*end > len) *end = len;
    else if (*end < 0) {
        *end += len;
        if (*end < 0) *end = 0;
    }
    if (*start < 0) {
        *start += len;
        if (*start < 0) *start = 0;
    }
}

i64 avp_str_find(AvpStr hay, AvpStr needle, i64 start, i64 end) {
    adjust(&start, &end, (i64)hay.n);
    if (end - start < (i64)needle.n) return -1;
    if (needle.n == 0) return start;
    const char *r = search_fwd(hay.p + start, (size_t)(end - start), needle.p, needle.n);
    return r ? (i64)(r - hay.p) : -1;
}

i64 avp_str_rfind(AvpStr hay, AvpStr needle, i64 start, i64 end) {
    adjust(&start, &end, (i64)hay.n);
    if (end - start < (i64)needle.n) return -1;
    if (needle.n == 0) return end;
    const char *r = search_rev(hay.p + start, (size_t)(end - start), needle.p, needle.n);
    return r ? (i64)(r - hay.p) : -1;
}

bool avp_str_contains(AvpStr hay, AvpStr needle) {
    if (needle.n == 0) return true;
    return search_fwd(hay.p, hay.n, needle.p, needle.n) != NULL;
}

size_t avp_str_count(AvpStr hay, AvpStr needle) {
    if (needle.n == 0) return avp_u8_len(hay) + 1; /* between every code point and at both ends */
    size_t count = 0;
    const char *p = hay.p, *end = hay.p + hay.n;
    for (;;) {
        const char *r = search_fwd(p, (size_t)(end - p), needle.p, needle.n);
        if (!r) return count;
        count++;
        p = r + needle.n;
    }
}

i64 avp_str_findc(AvpStr s, char c) {
    if (s.n == 0) return -1;
    const char *r = (const char *)memchr(s.p, (u8)c, s.n);
    return r ? (i64)(r - s.p) : -1;
}

AvpStr avp_str_slice(AvpStr s, i64 i, i64 j) {
    i64 len = (i64)s.n;
    if (i < 0) {
        i += len;
        if (i < 0) i = 0;
    } else if (i > len) {
        i = len;
    }
    if (j < 0) {
        j += len;
        if (j < 0) j = 0;
    } else if (j > len) {
        j = len;
    }
    if (j < i) j = i;
    return avp_strn(s.p + i, (size_t)(j - i));
}

/* ---- strip -------------------------------------------------------------------------------------------------------- */

AvpStr avp_str_lstrip(AvpStr s) {
    const char *p = s.p, *end = s.p + s.n;
    while (p < end) {
        const char *q = p;
        u32 cp = (u8)*p < 0x80 ? (u32)(u8)*q++ : avp_u8_next(&q, end);
        if (!avp_cp_isspace(cp)) break;
        p = q;
    }
    return avp_strn(p, (size_t)(end - p));
}

AvpStr avp_str_rstrip(AvpStr s) {
    const char *end = s.p + s.n;
    while (end > s.p) {
        const char *q = end;
        u32 cp = avp__u8_prev(s.p, &q);
        if (!avp_cp_isspace(cp)) break;
        end = q;
    }
    return avp_strn(s.p, (size_t)(end - s.p));
}

AvpStr avp_str_strip(AvpStr s) { return avp_str_rstrip(avp_str_lstrip(s)); }

static bool in_charset(AvpStr chars, u32 cp) {
    const char *p = chars.p, *end = chars.p + chars.n;
    while (p < end)
        if (avp_u8_next(&p, end) == cp) return true;
    return false;
}

AvpStr avp_str_lstrip_chars(AvpStr s, AvpStr chars) {
    const char *p = s.p, *end = s.p + s.n;
    while (p < end) {
        const char *q = p;
        u32 cp = avp_u8_next(&q, end);
        if (!in_charset(chars, cp)) break;
        p = q;
    }
    return avp_strn(p, (size_t)(end - p));
}

AvpStr avp_str_rstrip_chars(AvpStr s, AvpStr chars) {
    const char *end = s.p + s.n;
    while (end > s.p) {
        const char *q = end;
        u32 cp = avp__u8_prev(s.p, &q);
        if (!in_charset(chars, cp)) break;
        end = q;
    }
    return avp_strn(s.p, (size_t)(end - s.p));
}

AvpStr avp_str_strip_chars(AvpStr s, AvpStr chars) {
    return avp_str_rstrip_chars(avp_str_lstrip_chars(s, chars), chars);
}

AvpStr avp_str_removeprefix(AvpStr s, AvpStr prefix) {
    if (prefix.n && avp_str_startswith(s, prefix)) return avp_strn(s.p + prefix.n, s.n - prefix.n);
    return s;
}

AvpStr avp_str_removesuffix(AvpStr s, AvpStr suffix) {
    if (suffix.n && avp_str_endswith(s, suffix)) return avp_strn(s.p, s.n - suffix.n);
    return s;
}

/* ---- split -------------------------------------------------------------------------------------------------------- */

static void push_view(AvpStrVec *v, const char *p, size_t n) {
    AvpStr s;
    s.p = p;
    s.n = n;
    avp_vec_push(v, s);
}

/* The code point at p (p < end) and its byte length. */
static inline u32 cp_at(const char *p, const char *end, size_t *len) {
    if ((u8)*p < 0x80) {
        *len = 1;
        return (u8)*p;
    }
    const char *q = p;
    u32 cp = avp_u8_next(&q, end);
    *len = (size_t)(q - p);
    return cp;
}

static AvpStrVec split_whitespace(AvpStr s, int maxsplit) {
    AvpStrVec v = {0};
    const char *p = s.p, *end = s.p + s.n;
    size_t l;
    while (maxsplit != 0) {
        while (p < end && avp_cp_isspace(cp_at(p, end, &l))) p += l;
        if (p == end) break;
        const char *start = p;
        while (p < end && !avp_cp_isspace(cp_at(p, end, &l))) p += l;
        push_view(&v, start, (size_t)(p - start));
        if (maxsplit > 0) maxsplit--;
    }
    if (p < end) {
        /* Only when the limit was reached: skip whitespace, the rest (trailing whitespace included) is the last field. */
        while (p < end && avp_cp_isspace(cp_at(p, end, &l))) p += l;
        if (p < end) push_view(&v, p, (size_t)(end - p));
    }
    return v;
}

AvpStrVec avp_str_split(AvpStr s, AvpStr sep, int maxsplit) {
    if (sep.n == 0) return split_whitespace(s, maxsplit);
    AvpStrVec v = {0};
    const char *p = s.p, *end = s.p + s.n;
    while (maxsplit != 0) {
        const char *r = search_fwd(p, (size_t)(end - p), sep.p, sep.n);
        if (!r) break;
        push_view(&v, p, (size_t)(r - p));
        p = r + sep.n;
        if (maxsplit > 0) maxsplit--;
    }
    push_view(&v, p, (size_t)(end - p));
    return v;
}

static void reverse_vec(AvpStrVec *v) {
    for (size_t i = 0, j = v->n; i + 1 < j; i++, j--) {
        AvpStr t = v->v[i];
        v->v[i] = v->v[j - 1];
        v->v[j - 1] = t;
    }
}

AvpStrVec avp_str_rsplit(AvpStr s, AvpStr sep, int maxsplit) {
    AvpStrVec v = {0};
    const char *begin = s.p, *end = s.p + s.n;
    if (sep.n == 0) {
        while (maxsplit != 0) {
            while (end > begin) {
                const char *q = end;
                if (!avp_cp_isspace(avp__u8_prev(begin, &q))) break;
                end = q;
            }
            if (end == begin) break;
            const char *stop = end;
            while (end > begin) {
                const char *q = end;
                if (avp_cp_isspace(avp__u8_prev(begin, &q))) break;
                end = q;
            }
            push_view(&v, end, (size_t)(stop - end));
            if (maxsplit > 0) maxsplit--;
        }
        if (end > begin) {
            /* Only when the limit was reached: the rest, leading whitespace included, minus trailing whitespace. */
            while (end > begin) {
                const char *q = end;
                if (!avp_cp_isspace(avp__u8_prev(begin, &q))) break;
                end = q;
            }
            if (end > begin) push_view(&v, begin, (size_t)(end - begin));
        }
        reverse_vec(&v);
        return v;
    }
    while (maxsplit != 0) {
        const char *r = search_rev(begin, (size_t)(end - begin), sep.p, sep.n);
        if (!r) break;
        push_view(&v, r + sep.n, (size_t)(end - (r + sep.n)));
        end = r;
        if (maxsplit > 0) maxsplit--;
    }
    push_view(&v, begin, (size_t)(end - begin));
    reverse_vec(&v);
    return v;
}

/* Length of the line boundary starting at p (0 when none): \n \r \r\n \v \f \x1c \x1d \x1e U+0085 U+2028 U+2029. */
static size_t line_break_len(const char *p, const char *end) {
    u8 c = (u8)*p;
    if (c == '\r') return (p + 1 < end && p[1] == '\n') ? 2 : 1;
    if (c == '\n' || c == 0x0B || c == 0x0C || (c >= 0x1C && c <= 0x1E)) return 1;
    if (c == 0xC2 && p + 1 < end && (u8)p[1] == 0x85) return 2;
    if (c == 0xE2 && p + 2 < end && (u8)p[1] == 0x80 && ((u8)p[2] == 0xA8 || (u8)p[2] == 0xA9)) return 3;
    return 0;
}

AvpStrVec avp_str_splitlines(AvpStr s, bool keepends) {
    AvpStrVec v = {0};
    const char *p = s.p, *end = s.p + s.n, *start = p;
    while (p < end) {
        size_t bl = (u8)*p < 0x20 || (u8)*p >= 0x80 ? line_break_len(p, end) : 0;
        if (bl) {
            push_view(&v, start, (size_t)(p - start) + (keepends ? bl : 0));
            p += bl;
            start = p;
        } else {
            p++;
        }
    }
    if (start < end) push_view(&v, start, (size_t)(end - start));
    return v;
}

bool avp_str_partition(AvpStr s, AvpStr sep, AvpStr *before, AvpStr *after) {
    AVP_ASSERT(sep.n > 0); /* Python raises ValueError("empty separator") */
    const char *r = search_fwd(s.p, s.n, sep.p, sep.n);
    if (!r) {
        *before = s;
        *after = avp_strn(s.p + s.n, 0);
        return false;
    }
    *before = avp_strn(s.p, (size_t)(r - s.p));
    *after = avp_strn(r + sep.n, (size_t)(s.p + s.n - (r + sep.n)));
    return true;
}

bool avp_str_rpartition(AvpStr s, AvpStr sep, AvpStr *before, AvpStr *after) {
    AVP_ASSERT(sep.n > 0);
    const char *r = search_rev(s.p, s.n, sep.p, sep.n);
    if (!r) {
        *before = avp_strn(s.p, 0); /* Python: ('', '', s) */
        *after = s;
        return false;
    }
    *before = avp_strn(s.p, (size_t)(r - s.p));
    *after = avp_strn(r + sep.n, (size_t)(s.p + s.n - (r + sep.n)));
    return true;
}

/* ---- replace, join, concat, repeat -------------------------------------------------------------------------------- */

static AvpStr finish(char *p, size_t n) {
    p[n] = 0;
    return avp_strn(p, n);
}

AvpStr avp_str_replace(AvpArena *a, AvpStr s, AvpStr old, AvpStr new_, int count) {
    if (count == 0) return s;
    if (old.n == 0) {
        /* Python inserts `new` before every code point and at the end: len + 1 places, the first `count` of them. */
        size_t places = avp_u8_len(s) + 1;
        size_t k = (count < 0 || (size_t)count > places) ? places : (size_t)count;
        if (new_.n && k > (SIZE_MAX - s.n - 1) / new_.n) avp_fatal("out of memory (replace)");
        char *out = (char *)avp_alloc_noz(a, s.n + k * new_.n + 1);
        char *o = out;
        const char *p = s.p, *end = s.p + s.n;
        for (size_t i = 0; i < k; i++) {
            memcpy(o, new_.p, new_.n);
            o += new_.n;
            if (p < end) {
                const char *q = p;
                if ((u8)*q < 0x80) q++;
                else avp_u8_next(&q, end);
                memcpy(o, p, (size_t)(q - p));
                o += q - p;
                p = q;
            }
        }
        memcpy(o, p, (size_t)(end - p));
        o += end - p;
        return finish(out, (size_t)(o - out));
    }
    /* Find the matches first, so that the result is allocated once. */
    size_t found = 0;
    const char *p = s.p, *end = s.p + s.n;
    while (count < 0 || found < (size_t)count) {
        const char *r = search_fwd(p, (size_t)(end - p), old.p, old.n);
        if (!r) break;
        found++;
        p = r + old.n;
    }
    if (found == 0) return s;
    size_t out_n;
    if (new_.n >= old.n) {
        if ((new_.n - old.n) && found > (SIZE_MAX - s.n - 1) / (new_.n - old.n)) avp_fatal("out of memory (replace)");
        out_n = s.n + found * (new_.n - old.n);
    } else {
        out_n = s.n - found * (old.n - new_.n);
    }
    char *out = (char *)avp_alloc_noz(a, out_n + 1);
    char *o = out;
    p = s.p;
    for (size_t i = 0; i < found; i++) {
        const char *r = search_fwd(p, (size_t)(end - p), old.p, old.n);
        memcpy(o, p, (size_t)(r - p));
        o += r - p;
        memcpy(o, new_.p, new_.n);
        o += new_.n;
        p = r + old.n;
    }
    memcpy(o, p, (size_t)(end - p));
    o += end - p;
    return finish(out, (size_t)(o - out));
}

AvpStr avp_str_join(AvpArena *a, AvpStr sep, const AvpStr *items, size_t count) {
    if (count == 0) return finish((char *)avp_alloc_noz(a, 1), 0);
    size_t total = sep.n * (count - 1);
    for (size_t i = 0; i < count; i++) {
        if (items[i].n > SIZE_MAX / 2 - total) avp_fatal("out of memory (join)");
        total += items[i].n;
    }
    char *out = (char *)avp_alloc_noz(a, total + 1);
    char *o = out;
    for (size_t i = 0; i < count; i++) {
        if (i && sep.n) {
            memcpy(o, sep.p, sep.n);
            o += sep.n;
        }
        if (items[i].n) memcpy(o, items[i].p, items[i].n);
        o += items[i].n;
    }
    return finish(out, total);
}

AvpStr avp_str_concat(AvpArena *a, AvpStr x, AvpStr y) {
    char *out = (char *)avp_alloc_noz(a, x.n + y.n + 1);
    if (x.n) memcpy(out, x.p, x.n);
    if (y.n) memcpy(out + x.n, y.p, y.n);
    return finish(out, x.n + y.n);
}

AvpStr avp_str_repeat(AvpArena *a, AvpStr s, size_t times) {
    if (s.n && times > (SIZE_MAX / 2) / s.n) avp_fatal("out of memory (repeat)");
    size_t total = s.n * times;
    char *out = (char *)avp_alloc_noz(a, total + 1);
    if (s.n == 1) memset(out, (u8)s.p[0], times);
    else
        for (size_t i = 0; i < times; i++) memcpy(out + i * s.n, s.p, s.n);
    return finish(out, total);
}

/* ---- tabs and padding --------------------------------------------------------------------------------------------- */

AvpStr avp_str_expandtabs(AvpArena *a, AvpStr s, int tabsize) {
    AvpBuf b;
    avp_buf_init(&b, a);
    avp_buf_reserve(&b, s.n);
    const char *p = s.p, *end = s.p + s.n;
    i64 col = 0;
    while (p < end) {
        char c = *p;
        if (c == '\t') {
            /* tabsize <= 0 removes the tab; the column is not advanced then, as in Python. */
            if (tabsize > 0) {
                i64 add = tabsize - col % tabsize;
                col += add;
                for (i64 i = 0; i < add; i++) avp_buf_putc(&b, ' ');
            }
            p++;
            continue;
        }
        const char *q = p;
        if ((u8)c < 0x80) q++;
        else avp_u8_next(&q, end);
        avp_buf_putn(&b, p, (size_t)(q - p));
        col++;
        if (c == '\n' || c == '\r') col = 0;
        p = q;
    }
    avp_buf_putn(&b, "", 0);
    return avp_buf_str(&b);
}

static AvpStr pad(AvpArena *a, AvpStr s, size_t width, u32 fill, size_t left, size_t right) {
    (void)width;
    char fb[4];
    size_t fn = avp_u8_put(fb, fill);
    char *out = (char *)avp_alloc_noz(a, s.n + (left + right) * fn + 1);
    char *o = out;
    for (size_t i = 0; i < left; i++, o += fn) memcpy(o, fb, fn);
    if (s.n) memcpy(o, s.p, s.n);
    o += s.n;
    for (size_t i = 0; i < right; i++, o += fn) memcpy(o, fb, fn);
    return finish(out, (size_t)(o - out));
}

AvpStr avp_str_ljust(AvpArena *a, AvpStr s, size_t width, u32 fill) {
    size_t len = avp_u8_len(s);
    if (len >= width) return s;
    return pad(a, s, width, fill, 0, width - len);
}

AvpStr avp_str_rjust(AvpArena *a, AvpStr s, size_t width, u32 fill) {
    size_t len = avp_u8_len(s);
    if (len >= width) return s;
    return pad(a, s, width, fill, width - len, 0);
}

AvpStr avp_str_center(AvpArena *a, AvpStr s, size_t width, u32 fill) {
    size_t len = avp_u8_len(s);
    if (len >= width) return s;
    size_t marg = width - len;
    size_t left = marg / 2 + (marg & width & 1); /* CPython's rule for the odd column */
    return pad(a, s, width, fill, left, marg - left);
}

AvpStr avp_str_zfill(AvpArena *a, AvpStr s, size_t width) {
    size_t len = avp_u8_len(s);
    if (len >= width) return s;
    size_t fill = width - len;
    char *out = (char *)avp_alloc_noz(a, s.n + fill + 1);
    size_t sign = (s.n && (s.p[0] == '+' || s.p[0] == '-')) ? 1 : 0;
    if (sign) out[0] = s.p[0];
    memset(out + sign, '0', fill);
    memcpy(out + sign + fill, s.p + sign, s.n - sign);
    return finish(out, s.n + fill);
}

/* ---- UTF-16 ------------------------------------------------------------------------------------------------------- */

wchar_t *avp_to_w(AvpArena *a, AvpStr s) {
    wchar_t *out = (wchar_t *)avp_alloc_noz(a, (s.n + 1) * sizeof(wchar_t));
    wchar_t *o = out;
    const char *p = s.p, *end = s.p + s.n;
    while (p < end) {
        u32 cp = (u8)*p < 0x80 ? (u32)(u8)*p++ : avp_u8_next(&p, end);
        if (cp >= 0x10000) {
            cp -= 0x10000;
            *o++ = (wchar_t)(0xD800 + (cp >> 10));
            *o++ = (wchar_t)(0xDC00 + (cp & 0x3FF));
        } else {
            *o++ = (wchar_t)cp;
        }
    }
    *o = 0;
    return out;
}

wchar_t *avp_to_wz(AvpArena *a, const char *cz) { return avp_to_w(a, avp_str(cz)); }

AvpStr avp_from_w(AvpArena *a, const wchar_t *w, i64 n) {
    size_t len = n < 0 ? wcslen(w) : (size_t)n;
    char *out = (char *)avp_alloc_noz(a, len * 3 + 1);
    char *o = out;
    for (size_t i = 0; i < len; i++) {
        u32 c = w[i];
        if (c >= 0xD800 && c <= 0xDBFF && i + 1 < len && w[i + 1] >= 0xDC00 && w[i + 1] <= 0xDFFF) {
            c = 0x10000 + ((c - 0xD800) << 10) + (w[i + 1] - 0xDC00);
            i++;
        } else if (c >= 0xD800 && c <= 0xDFFF) {
            c = 0xFFFD; /* an unpaired surrogate */
        }
        o += avp_u8_put(o, c);
    }
    size_t used = (size_t)(o - out);
    out = (char *)avp_arena_realloc(a, out, len * 3 + 1, used + 1);
    return finish(out, used);
}

/* ---- builder ------------------------------------------------------------------------------------------------------ */

void avp_buf_init(AvpBuf *b, AvpArena *a) {
    b->p = NULL;
    b->n = 0;
    b->cap = 0;
    b->a = a;
}

void avp_buf_reserve(AvpBuf *b, size_t extra) {
    if (extra > SIZE_MAX / 4 - b->n) avp_fatal("out of memory (string builder)");
    size_t need = b->n + extra + 1;
    if (need <= b->cap) return;
    size_t ncap = b->cap * 2;
    if (ncap < need) ncap = need;
    if (ncap < 64) ncap = 64;
    if (b->a) b->p = (char *)avp_arena_realloc(b->a, b->p, b->cap, ncap);
    else b->p = (char *)avp_xrealloc(b->p, ncap);
    b->cap = ncap;
}

void avp_buf_putn(AvpBuf *b, const void *p, size_t n) {
    avp_buf_reserve(b, n);
    if (n) memcpy(b->p + b->n, p, n);
    b->n += n;
    b->p[b->n] = 0;
}

void avp_buf_put(AvpBuf *b, AvpStr s) { avp_buf_putn(b, s.p, s.n); }
void avp_buf_putz(AvpBuf *b, const char *cz) { avp_buf_putn(b, cz, strlen(cz)); }

void avp_buf_putc(AvpBuf *b, char c) {
    avp_buf_reserve(b, 1);
    b->p[b->n++] = c;
    b->p[b->n] = 0;
}

void avp_buf_putcp(AvpBuf *b, u32 cp) {
    char t[4];
    size_t n = avp_u8_put(t, cp);
    avp_buf_putn(b, t, n);
}

void avp_buf_vprintf(AvpBuf *b, const char *fmt, va_list ap) {
    va_list ap2;
    va_copy(ap2, ap);
    int need = vsnprintf(b->p ? b->p + b->n : NULL, b->p ? b->cap - b->n : 0, fmt, ap2);
    va_end(ap2);
    if (need < 0) avp_panic(__FILE__, __LINE__, "vsnprintf failed for \"%s\"", fmt);
    if (b->p && (size_t)need < b->cap - b->n) {
        b->n += (size_t)need;
        return;
    }
    avp_buf_reserve(b, (size_t)need);
    vsnprintf(b->p + b->n, (size_t)need + 1, fmt, ap);
    b->n += (size_t)need;
}

void avp_buf_printf(AvpBuf *b, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    avp_buf_vprintf(b, fmt, ap);
    va_end(ap);
}

void avp_buf_clear(AvpBuf *b) {
    b->n = 0;
    if (b->p) b->p[0] = 0;
}

AvpStr avp_buf_str(const AvpBuf *b) { return avp_strn(b->p, b->n); }

char *avp_buf_cz(AvpBuf *b) {
    if (!b->p) return (char *)"";
    b->p[b->n] = 0;
    return b->p;
}

void avp_buf_free(AvpBuf *b) {
    if (!b->a) avp_xfree(b->p);
    b->p = NULL;
    b->n = b->cap = 0;
}
